import { GBNF } from './gbnf.ts';

const readStdin = async (): Promise<string> => {
  const chunks: Buffer[] = [];
  for await (const chunk of process.stdin) {
    chunks.push(chunk as Buffer);
  }
  return Buffer.concat(chunks).toString('utf8');
};

const main = async () => {
  const cases = JSON.parse(await readStdin());
  const results: unknown[] = [];
  for (const testCase of cases) {
    const steps: unknown[] = [];
    try {
      let state = GBNF(testCase.grammar, testCase.initial ?? '');
      steps.push({ rules: [...state] });
      for (const add of (testCase.adds ?? [])) {
        state = state.add(add);
        steps.push({ rules: [...state] });
      }
    } catch (err: any) {
      steps.push({ error: { name: err.name, message: err.message } });
    }
    results.push({ steps });
  }
  process.stdout.write(JSON.stringify(results, null, 2));
};

await main();

